export function Contact() {
  const [status,setStatus] = useState("idle");
  const submit = async (event) => { event.preventDefault(); const form=event.currentTarget; const data=new FormData(form); setStatus("loading"); try { const response=await submitContactEnquiry({ firstName:String(data.get("firstName")||"").trim(), lastName:String(data.get("lastName")||"").trim(), email:String(data.get("email")||"").trim(), phone:String(data.get("phone")||"").trim(), registration:String(data.get("registration")||"").trim().toUpperCase(), service:String(data.get("service")||"").trim(), message:String(data.get("message")||"").trim(), consent:true, source:"website" }); if (!response?.success) throw new Error(response?.message || "We could not send your enquiry. Please try again."); form.reset(); setStatus("done"); toast.success(response.message || "Your enquiry has been received."); } catch(error) { setStatus("idle"); toast.error(error.message || "We could not send your enquiry. Please try again."); } };
  return <Layout><section className="ms-page-hero ms-page-hero--contact"><div className="ms-wrap"><Label>CONTACT / 02</Label><h1>LET’S TALK<br /><em>ABOUT YOUR BIKE.</em></h1><p>Planning a service or noticed something unusual? Give us a few details and we’ll take it from there.</p><span className="ms-page-hero__mark">02</span></div></section><section className="ms-section ms-contact"><div className="ms-wrap ms-contact__grid"><div className="ms-contact__intro"><Label>START A CONVERSATION</Label><h2>EVERY GOOD RIDE<br /><em>STARTS HERE.</em></h2><p>Share your bike’s registration, model and the work you have in mind. The more detail you give us, the better we can understand your enquiry.</p><div className="ms-contact__note"><ShieldCheck size={22} /><div><strong>YOUR BIKE, YOUR DECISION</strong><p>We’ll discuss the work with you before it goes ahead.</p></div></div></div><div className="ms-form-card">{status === "done" ? <div className="ms-success"><Check size={28} /><h3>Enquiry received.</h3><p>Thank you for getting in touch. The workshop will review your message.</p><button className="ms-action" onClick={()=>setStatus("idle")}>SEND ANOTHER <ArrowRight size={17} /></button></div> : <form onSubmit={submit}><Label>ENQUIRY FORM</Label><h3>Tell us what you need.</h3><div className="ms-form-grid"><label>First name<input name="firstName" required autoComplete="given-name" placeholder="Your first name" /></label><label>Last name<input name="lastName" required autoComplete="family-name" placeholder="Your last name" /></label><label>Email address<input name="email" required type="email" autoComplete="email" placeholder="you@example.com" /></label><label>Phone number<input name="phone" required type="tel" autoComplete="tel" placeholder="Your phone number" /></label><label>Bike registration <small>OPTIONAL</small><input name="registration" placeholder="Registration number" /></label><label>Service needed<select name="service" required defaultValue=""><option value="" disabled>Choose a service</option>{services.map(s=><option key={s.title}>{s.title}</option>)}<option>Not sure yet</option></select></label><label className="ms-form-full">Tell us about your bike<textarea name="message" required rows="4" placeholder="Bike make, model, mileage and anything you’ve noticed..." /></label></div><p className="ms-form-note">By sending this enquiry, you agree that the workshop may contact you about it.</p><button className="ms-action" disabled={status === "loading"}>{status === "loading" ? "SENDING…" : "SEND ENQUIRY"}<ArrowRight size={17} /></button></form>}</div></div></section></Layout>;
}

export function Vehicle() {
  const [query,setQuery]=useState(""); const [status,setStatus]=useState("idle"); const [result,setResult]=useState(null);
  const search=async(event)=>{event.preventDefault(); const registration=query.trim().toUpperCase().replace(/\s/g,""); if(!registration)return; setStatus("loading"); setResult(null); try {const data=await lookupVehicle(registration); if(data?.success===false){setStatus(Number(data.status)===404||data.code==="DVLA_NOT_FOUND"?"notfound":"error");return;} setResult({...data,registrationNumber:data.registrationNumber||registration}); setStatus("found");} catch {setStatus("error");}};
  const fields=result ? [["Registration",result.registrationNumber],["Make",result.make],["Model",result.model || result.typeApproval],["Engine",result.engineCapacity ? `${result.engineCapacity} cc` : null],["Colour",result.colour],["Year",result.yearOfManufacture],["Fuel",result.fuelType],["MOT status",result.motStatus],["Tax status",result.taxStatus]] : [];
  return <Layout><section className="ms-page-hero"><div className="ms-wrap"><Label>BIKE CHECK / 03</Label><h1>START WITH<br /><em>YOUR BIKE.</em></h1><p>Look up the available record using a UK registration before planning your workshop visit.</p><span className="ms-page-hero__mark">03</span></div></section><section className="ms-section ms-lookup"><div className="ms-wrap ms-lookup__grid"><div><Label>REGISTRATION LOOKUP</Label><h2>THE RIGHT DETAILS.<br /><em>A BETTER START.</em></h2><p>Enter the registration number to see the details returned by the connected UK vehicle record service. Availability depends on that service.</p><div className="ms-contact__note"><ShieldCheck size={22}/><div><strong>GOOD TO KNOW</strong><p>Check the returned details before relying on them. You can also contact us without using the lookup.</p></div></div></div><div className="ms-form-card"><Label>FIND A RECORD</Label><h3>Enter registration.</h3><form onSubmit={search} className="ms-lookup__form"><label>Registration number<input required value={query} onChange={e=>setQuery(e.target.value.toUpperCase())} placeholder="e.g. AB12 CDE" /></label><button className="ms-action" disabled={status==="loading"}><Search size={17}/>{status==="loading"?"SEARCHING…":"CHECK RECORD"}</button></form>{status==="notfound" && <p className="ms-feedback" role="status">No record was found. Check the registration and try again.</p>}{status==="error" && <p className="ms-feedback" role="alert">The lookup service is unavailable right now. Please try again later or contact the workshop.</p>}{status==="found" && <div className="ms-result"><h4>Available details</h4><div>{fields.map(([label,value])=><p key={label}><span>{label}</span><strong>{value || "—"}</strong></p>)}</div><Action to="/contact">ENQUIRE ABOUT YOUR BIKE</Action></div>}</div></div></section></Layout>;
}
